// §10.5 — Human Handoff entry point
// Triggered by: COMPLAINT, HUMAN_HANDOFF_REQUEST, or confidence < 0.6
const ctx = $input.item.json;

// Determine the handoff reason
let reason = 'low_confidence';
if (ctx.intent === 'COMPLAINT')              reason = 'complaint';
if (ctx.intent === 'HUMAN_HANDOFF_REQUEST') reason = 'customer_request';

return [{ json: { ...ctx, handoff_reason: reason } }];

// Build chat snapshot and AI context for the handoff
const ctx = $('Handoff Entry').item.json;
let chatArray = [];

// The Postgres node returns a single item with a 'chat_snapshot' property containing the array
try {
  const rawHistory = $input.item.json.chat_snapshot;
  if (Array.isArray(rawHistory)) {
    chatArray = rawHistory;
  } else if (typeof rawHistory === 'string') {
    chatArray = JSON.parse(rawHistory);
  }
} catch (e) {
  chatArray = [];
}

const chatSnapshot = chatArray.map(msg => ({
  direction:  msg.direction || 'unknown',
  text:       msg.message_text || '',
  intent:     msg.detected_intent || '',
  confidence: msg.confidence || 0,
  at:         msg.created_at || ''
}));

const chatText = chatArray
  .slice().reverse()
  .map(m => `[${(m.direction || 'unknown').toUpperCase()}] ${m.message_text || ''}`)
  .join('\n');

return [{
  json: {
    ...ctx,
    chat_snapshot: JSON.stringify(chatSnapshot),
    chat_text:     chatText || '(No previous messages)'
  }
}];

// Parse AI Agent suggested reply for handoff
const aiText = $input.item.json.output ?? $input.item.json.text ?? 'Our team will look into your concern and get back to you shortly.';
const ctx = $('Build Chat Snapshot').item.json;
const ticketId = $('Create Support Ticket').item.json.ticket_id;

return [{
  json: {
    ...ctx,
    ticket_id: ticketId,
    suggested_reply: aiText.trim()
  }
}];

